viewof frames = {
  const container = html`&lt;div style="margin-bottom: 20px;"&gt;
    &lt;h3&gt;Your 9-frame sequence:&lt;/h3&gt;
    &lt;div id="frame-display" style="display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 15px; min-height: 50px;"&gt;&lt;/div&gt;
    &lt;div style="margin-bottom: 10px;"&gt;
      &lt;strong&gt;Add a frame:&lt;/strong&gt;
    &lt;/div&gt;
    &lt;div&gt;
      &lt;button class="frame-btn strike" onclick="addFrame('strike')"&gt;Strike (X)&lt;/button&gt;
      &lt;button class="frame-btn spare" onclick="addFrame('spare55')"&gt;Spare (5,5)&lt;/button&gt;
      &lt;button class="frame-btn spare" onclick="addFrame('spare73')"&gt;Spare (7,3)&lt;/button&gt;
      &lt;button class="frame-btn spare" onclick="addFrame('spare91')"&gt;Spare (9,1)&lt;/button&gt;
      &lt;button class="frame-btn open" onclick="addFrame('open54')"&gt;Open (5,4)&lt;/button&gt;
      &lt;button class="frame-btn open" onclick="addFrame('open81')"&gt;Open (8,1)&lt;/button&gt;
      &lt;button class="frame-btn open" onclick="addFrame('open32')"&gt;Open (3,2)&lt;/button&gt;
    &lt;/div&gt;
    &lt;div style="margin-top: 10px;"&gt;
      &lt;button onclick="undoFrame()" style="padding: 6px 16px; margin-right: 8px;"&gt;Undo&lt;/button&gt;
      &lt;button onclick="clearFrames()" style="padding: 6px 16px;"&gt;Clear All&lt;/button&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;

  let currentFrames = [];

  const frameLabels = {
    'strike': 'X',
    'spare55': '5/',
    'spare73': '7/',
    'spare91': '9/',
    'open54': '5,4',
    'open81': '8,1',
    'open32': '3,2'
  };

  const frameBalls = {
    'strike': [10],
    'spare55': [5, 5],
    'spare73': [7, 3],
    'spare91': [9, 1],
    'open54': [5, 4],
    'open81': [8, 1],
    'open32': [3, 2]
  };

  function frameColor(type) {
    if (type === 'strike') return '#1a1a1a';
    if (type.startsWith('spare')) return '#888888';
    return '#cccccc';
  }

  function render() {
    const display = container.querySelector('#frame-display');
    display.innerHTML = '';
    currentFrames.forEach((f, i) =&gt; {
      const el = html`&lt;div style="
        padding: 10px 16px;
        border-radius: 6px;
        background: ${frameColor(f)};
        color: ${f.startsWith('open') ? 'black' : 'white'};
        font-weight: bold;
        font-size: 1.1em;
        text-align: center;
        min-width: 40px;
      "&gt;F${i+1}&lt;br&gt;${frameLabels[f]}&lt;/div&gt;`;
      display.appendChild(el);
    });
    if (currentFrames.length &lt; 9) {
      const remaining = html`&lt;div style="
        padding: 10px 16px; border: 2px dashed #ccc; border-radius: 6px;
        color: #999; text-align: center; min-width: 40px;
      "&gt;F${currentFrames.length + 1}&lt;br&gt;?&lt;/div&gt;`;
      display.appendChild(remaining);
    }
    // Always show frame 10
    const f10 = html`&lt;div style="
      padding: 10px 16px; border-radius: 6px;
      background: #f0f0f0; border: 1px solid #ccc;
      color: #666; text-align: center; min-width: 40px;
    "&gt;F10&lt;br&gt;5,4&lt;/div&gt;`;
    display.appendChild(f10);

    container.value = [...currentFrames];
    container.dispatchEvent(new Event("input"));
  }

  window.addFrame = function(type) {
    if (currentFrames.length &lt; 9) {
      currentFrames.push(type);
      render();
    }
  };

  window.undoFrame = function() {
    currentFrames.pop();
    render();
  };

  window.clearFrames = function() {
    currentFrames = [];
    render();
  };

  render();
  return container;
}
frameBallsMap = ({
  'strike': [10],
  'spare55': [5, 5],
  'spare73': [7, 3],
  'spare91': [9, 1],
  'open54': [5, 4],
  'open81': [8, 1],
  'open32': [3, 2]
})

balls = {
  if (frames.length &lt; 9) return null;
  let b = [];
  for (let f of frames) {
    b = b.concat(frameBallsMap[f]);
  }
  b = b.concat([5, 4]); // frame 10
  return b;
}

tradScore = balls ? scoreTraditional(balls) : null
worldScore = balls ? scoreWorld(balls) : null
html`&lt;div style="text-align: center; margin-top: 10px; color: #666; font-style: italic;"&gt;
  ${frames.length &lt; 9
    ? `Add ${9 - frames.length} more frame${9 - frames.length &gt; 1 ? 's' : ''} to see scores`
    : tradScore !== null && worldScore !== null
      ? `Difference: ${tradScore - worldScore &gt; 0 ? '+' : ''}${tradScore - worldScore} (Traditional ${tradScore &gt; worldScore ? 'higher' : tradScore &lt; worldScore ? 'lower' : '= World Bowling'})`
      : ''}
&lt;/div&gt;`
